local _, ns = ...
local Translate = ns.Lore.Translate

Translate("frFR", "stonetalon-mountains", {
	title = "Les Serres-Rocheuses",
	aliases = { "Serres-Rocheuses" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Serres-Rocheuses sont un rempart de pics gris et de profondes vallées vertes à l'ouest de {link:kalimdor}Kalimdor{/link}, entre les forêts d'{link:ashenvale}Orneval{/link} au nord et les plaines de {link:mulgore}Mulgore{/link} et des {link:the-barrens}Tarides{/link} au sud et à l'est. À leur sommet se dresse le {link:stonetalon-peak}Pic des Serres-Rocheuses{/link}, une hauteur tenue pour sacrée depuis longtemps par les druides des {link:night-elves}elfes de la nuit{/link}. En contrebas, la terre descend en lacs, en gorges et en forêts d'arbres immenses. Beaucoup de ces arbres ont disparu. La {link:venture-company}KapitalRisk{/link} est venue aux Serres-Rocheuses avec ses scies et son feu, et là où ses machines sont passées, les esprits de la terre crient de douleur.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne dit comment les montagnes furent élevées, ni qui les nomma le premier. Ce que l'on sait, c'est que les Serres-Rocheuses étaient un lieu saint bien avant que les jeunes races ne viennent en {link:kalimdor}Kalimdor{/link}. Les druides {link:night-elves}kaldorei{/link} bâtirent l'antre des Serres haut sur le pic et y gardèrent leurs trésors. Parmi les pierres du sommet gisent les ruines d'une œuvre plus ancienne encore : un temple de l'époque de la {link:queen-azshara}reine Azshara{/link}, dont les bâtisseurs ne sont rappelés que par peu et pleurés par moins encore. La forêt qui couvrait les vallées en contrebas était confiée aux fils et aux filles du demi-dieu Cénarius, et elle poussa sans être troublée plus longtemps qu'aucun mortel ne peut le compter.

Pendant la {link:third-war}Troisième Guerre{/link}, le pic entra dans l'histoire des jeunes races. C'est aux Serres-Rocheuses que {link:cairne-bloodhoof}Cairne Bloodhoof{/link} envoya le jeune chef de guerre {link:thrall}Thrall{/link}, à la recherche d'un Oracle qui demeurait dans la montagne. Là, les chefs de la {link:horde}Horde{/link} et les humains de {link:lordaeron}Lordaeron{/link} rencontrèrent le prophète qui les avait appelés à l'ouest, et apprirent qu'il était {link:medivh}Medivh{/link}.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Les Serres-Rocheuses sont une terre en guerre contre elle-même. Les gobelins de la {link:venture-company}KapitalRisk{/link} se sont abattus sur les forêts de la {link:windshear-crag}Combe des Cisailles{/link}, et leurs déchiqueteuses abattent en une heure ce qui a poussé en mille ans. Quand ils s'enfoncèrent dans le {link:the-charred-vale}Val calciné{/link}, quelque chose dans le val riposta, et les gobelins l'incendièrent dans leur retraite. Des élémentaires de feu arpentent désormais les cendres. Les {link:harpies}harpies{/link} Rouges-furies ont fait leurs nids parmi les collines noircies, et de là elles se répandent sur tout le continent.

Ni l'{link:alliance}Alliance{/link} ni la {link:horde}Horde{/link} ne veulent abandonner les montagnes. Les elfes de la nuit tiennent le {link:stonetalon-peak}Pic des Serres-Rocheuses{/link}, et une Sentinelle et un mage {link:gnomes}gnome{/link} luttent ensemble contre les gobelins à la lisière de la Combe des Cisailles. La Horde tient la {link:sun-rock-retreat}Retraite de Roche-Soleil{/link} au cœur de la chaîne, où taurens et orcs cherchent à guérir la terre. À {link:malaka-jin}Malaka'jin{/link}, à l'extrême sud, des trolls {link:darkspear-trolls}Darkspear{/link} chassent et brassent. Au sud-est, les {link:grimtotem-clan}Totem sinistre{/link} ont élevé leur propre camp de guerre. Tous s'accordent sur une chose : la KapitalRisk doit partir. Ils ne s'accordent guère sur autre chose.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les {link:night-elves}kaldorei{/link} du pic.{/b} Des druides et des {link:sentinels}Sentinelles{/link} gardent le {link:stonetalon-peak}Pic des Serres-Rocheuses{/link} et l'antre des Serres. Ils sont peu nombreux, et vigilants.
• {b}La {link:horde}Horde{/link} de {link:sun-rock-retreat}Roche-Soleil{/link}.{/b} {link:tauren}Taurens{/link}, orcs et ceux qui sont venus combattre à leurs côtés tiennent la Retraite de Roche-Soleil, le seul abri sûr entre les {link:the-barrens}Tarides{/link} et la {link:desolace}Désolace{/link}.
• {b}{link:venture-company}La KapitalRisk{/link}.{/b} Des bûcherons, des mineurs et des ingénieurs gobelins exploitent la {link:windshear-crag}Combe des Cisailles{/link} avec de grandes machines, gardés par des mercenaires.
• {b}Les harpies Rouges-furies.{/b} Elles nichent dans le {link:the-charred-vale}Val calciné{/link}, et leur reine les gouverne depuis ses collines de l'ouest.
• {b}Les Totem sinistre.{/b} Une bande de guerre de ce clan tauren tient le {link:grimtotem-post}Poste Totem sinistre{/link} au sud-est et attaque les villages de son propre peuple.
• {b}Kobolds, araignées et wyvernes.{/b} Des {link:kobolds}kobolds{/link} creusent les profondeurs du {link:boulderslide-ravine}Ravin des Eboulis{/link}. De grandes araignées chassent la nuit sur le {link:webwinder-path}Sentier des Tisseuses{/link}. Des wyvernes Pridewing nichent sur les hautes falaises.
• {b}Les trolls de {link:malaka-jin}Malaka'jin{/link}.{/b} Un village {link:darkspear-trolls}Darkspear{/link} se trouve au pied sud des montagnes, là où la route monte depuis les Tarides.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}L'âge des druides.{/b} Pendant des âges innombrables, les Serres-Rocheuses appartinrent à la forêt et à ceux qui la gardaient. Les druides du pic et les enfants de Cénarius gardaient les vallées vertes.
• {b}L'Oracle.{/b} Pendant la {link:third-war}Troisième Guerre{/link}, {link:thrall}Thrall{/link} vint aux Serres-Rocheuses à la recherche de l'Oracle, et là, le prophète {link:medivh}Medivh{/link} pressa orcs et humains de s'unir contre la venue de la {link:burning-legion}Légion ardente{/link}.
• {b}L'arrivée de la {link:horde}Horde{/link}.{/b} Après la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, la Horde et les taurens firent de {link:kalimdor}Kalimdor{/link} leur foyer. La {link:sun-rock-retreat}Retraite de Roche-Soleil{/link} fut élevée dans les montagnes, et les {link:darkspear-trolls}Darkspear{/link} s'installèrent à {link:malaka-jin}Malaka'jin{/link}. Aucune chronique ne donne l'année de l'un ou l'autre.
• {b}L'invasion gobeline.{/b} {link:venture-company}La KapitalRisk{/link} vint dans les montagnes pour couper du bois et extraire du minerai. Elle dépouilla la {link:windshear-crag}Combe des Cisailles{/link}, incendia le {link:the-charred-vale}Val calciné{/link} et empoisonna les esprits de la terre.
• {b}Aujourd'hui.{/b} Druides, chamans, {link:sentinels}Sentinelles{/link} et gnomes luttent désormais pour guérir ce que les gobelins ont brisé. Les gobelins ripostent, et les harpies, {link:grimtotem-clan}les Totem sinistre{/link} et les esprits du feu combattent tout le monde.]=],
		},
		{
			title = "Savoir des montagnes",
			text = [=[• Les chamans disent que les esprits des Serres-Rocheuses sont presque aveuglés par la douleur et la rage. Ceux qui savent écouter ces choses ont entendu la terre elle-même crier.
• On dit que les harpies Rouges-furies sont la source du fléau des harpies à travers {link:kalimdor}Kalimdor{/link}. Les Witchwing des {link:the-barrens}Tarides{/link} sont venues de ces montagnes.
• Haut sur le pic demeurait jadis l'un des fils aînés de Cénarius. Son nom était {link:keeper-ordanus}Ordanus{/link}, et il fut emmené en secret quand un ennemi vint le chasser.
• On dit que les graines de Gaïa du {link:mirkfallon-lake}Lac Mirkfallon{/link} résistent à la corruption. Les taurens les plantent dans les cendres du {link:the-charred-vale}Val calciné{/link}, dans l'espoir qu'une nouvelle forêt s'y élève un jour.
• Sous le {link:boulderslide-ravine}Ravin des Eboulis{/link}, des kobolds trouvèrent un cristal appelé résonite. Là où il gisait, quelque chose de plus ancien que les kobolds dormait.]=],
		},
	},
})

Translate("frFR", "stonetalon-peak", {
	title = "Pic des Serres-Rocheuses",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Pic des Serres-Rocheuses est la couronne des montagnes, un haut sommet verdoyant à l'extrême nord-ouest de la chaîne. Les elfes de la nuit le gardent depuis des âges, et en ces jours le gardien {link:keeper-albagorm}Albagorm{/link} veille sur lui avec une poignée de druides, de {link:sentinels}Sentinelles{/link} et de tréants amicaux. Une petite auberge accueille ceux qui l'atteignent, et des hippogriffes portent les nouvelles vers {link:ashenvale}Orneval{/link} et au-delà. Le pic est sacré pour les {link:night-elves}kaldorei{/link}, et pourtant il renferme des choses plus anciennes et plus étranges : les ruines d'un temple de l'époque d'{link:azshara}Azshara{/link}, et les caveaux de l'antre des Serres. C'est d'ici qu'{link:keeper-ordanus}Ordanus{/link}, un fils de Cénarius, fut emporté en lieu sûr.]=],
		},
	},
})

Translate("frFR", "the-talon-den", {
	title = "L'antre des Serres",
	aliases = { "Antre des Serres" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'antre des Serres se trouve dans les hauts creux de l'ouest du {link:stonetalon-peak}Pic des Serres-Rocheuses{/link}. Les druides le bâtirent pour y garder des objets de pouvoir, et ils conçurent un plan minutieux pour que ces trésors ne tombent pas entre de mauvaises mains : une clé cachée dans une lanterne à l'entrée, des caches dispersées dans l'antre, et un trésor qui ne s'ouvre qu'à trois clés réunies. Des druides de l'ordre cénarien le gardent encore, avec un gardien des portes, un maître des clés et les dryades et gardiens de {link:mirkfallon-lake}Mirkfallon{/link}. Un rare dragon féerique, Nal'taszar, a été aperçu parmi les arbres au-dessus.]=],
		},
	},
})

Translate("frFR", "sun-rock-retreat", {
	title = "Retraite de Roche-Soleil",
	aliases = { "Roche-Soleil" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Retraite de Roche-Soleil est la place forte de la {link:horde}Horde{/link} au cœur des {link:stonetalon-mountains}Serres-Rocheuses{/link}. Elle se dresse sur une butte rocheuse au milieu de la chaîne, gardée par des grunts orcs et accessible par des routes sinueuses depuis les {link:the-barrens}Tarides{/link} et la {link:desolace}Désolace{/link}. Ses chefs sont surtout des taurens. {link:maggran-earthbinder}Maggran Earthbinder{/link} commande sa défense. {link:tammra-windfield}Tammra Windfield{/link} et {link:mor-rogal}Mor'rogal{/link} soignent la terre blessée, tandis qu'un esprit de l'eau nommé {link:tsunaman}Tsunaman{/link} mène sa propre guerre contre le feu. Une auberge, un relais de coursiers du vent et une poignée de marchands en font un lieu où les voyageurs peuvent se reposer. C'est aussi là que la Horde rassemble ses forces contre les harpies, les gobelins et {link:grimtotem-clan}les Totem sinistre{/link}.]=],
		},
	},
})

Translate("frFR", "windshear-crag", {
	title = "Combe des Cisailles",
	aliases = { "Cisailles" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Combe des Cisailles est la grande vallée orientale des {link:stonetalon-mountains}Serres-Rocheuses{/link}, et le lieu où la {link:venture-company}KapitalRisk{/link} a fait le pire. Là où se dressait autrefois une vieille forêt, des souches couvrent maintenant les pentes. Des scieries et des roues à aubes bordent les ruisseaux, et les déchiqueteuses XT:4 et XT:9 arpentent les arbres. Au fond des collines, des gobelins et des mineurs à gages exploitent la Mine des Cisailles pour un étrange minerai vert doré. Quelque part dans la vallée, la compagnie entretient un petit port aérien pour ses machines volantes. À la lisière ouest de la combe, une Sentinelle {link:night-elves}elfe de la nuit{/link} et un mage {link:gnomes}gnome{/link} montent la garde ensemble, et non loin d'eux, un ingénieur gobelin, autrefois de la compagnie, complote contre ses anciens maîtres.]=],
		},
	},
})

Translate("frFR", "cragpool-lake", {
	title = "Lac de la Combe",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Lac de la Combe se trouve au nord de la {link:windshear-crag}Combe des Cisailles{/link}. Ses rives sont devenues le cœur des travaux de la {link:venture-company}KapitalRisk{/link} aux {link:stonetalon-mountains}Serres-Rocheuses{/link}. Une scierie se dresse au sud du lac, où la compagnie garde ses plans techniques. Haut au-dessus de l'eau, près d'une grande roue à aubes, le {link:gnomes}gnome{/link} {link:gerenzo-wrenchwhistle}Gerenzo Wrenchwhistle{/link} veille sur tout le chantier. Les voyageurs venus d'{link:ashenvale}Orneval{/link} qui descendent par la {link:the-talondeep-path}Perce des Serres{/link} doivent passer près du lac en route vers le sud-ouest et le pic.]=],
		},
	},
})

Translate("frFR", "mirkfallon-lake", {
	title = "Lac Mirkfallon",
	aliases = { "Mirkfallon" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Lac Mirkfallon est un grand lac rond au milieu du col de la montagne, au nord de la {link:sun-rock-retreat}Retraite de Roche-Soleil{/link}. Deux plantes remarquables poussent au bord de ses eaux. La première est la graine de Gaïa, que l'on trouve près de la rive, et que les taurens estiment parce qu'elle résiste à la corruption et peut ramener la vie sur une terre dévastée. La seconde est la mirkweed, dont les cosses prennent un rouge vif une fois séchées et donnent un beau pigment pour la peinture. Le lac est beau et sauvage, et ceux qui récoltent ses dons doivent se méfier des bêtes qui viennent y boire.]=],
		},
	},
})

Translate("frFR", "the-charred-vale", {
	title = "Le Val calciné",
	aliases = { "Val calciné", "Vallée des Rouges-furies" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Val calciné se trouve à l'ouest des montagnes, au sud du {link:stonetalon-peak}Pic des Serres-Rocheuses{/link}. C'était autrefois une forêt luxuriante. Quand la {link:venture-company}KapitalRisk{/link} s'y enfonça, les gardiens du val la repoussèrent, et les gobelins mirent le feu à la forêt en fuyant. Leurs armes corrompirent les tréants qui les combattaient, et l'incendie libéra des esprits ardents de flamme, de pierre et de rage. À présent, le val n'est que cendre et fumée. Les harpies Rouges-furies nichent dans ses collines, dans {link:stranglethorn-vale}la Vallée{/link} des Rouges-furies, et leur reine tient ses crêtes de l'ouest. Kaldorei et taurens rêvent tous de le rendre vert à nouveau.]=],
		},
	},
})

Translate("frFR", "greatwood-vale", {
	title = "Val de Grandbois",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Val de Grandbois se trouve au sud-est des {link:stonetalon-mountains}Serres-Rocheuses{/link}, là où la route venue de la {link:the-crossroads}Croisée{/link} sort des {link:the-barrens}Tarides{/link} et monte dans les montagnes. Son nom rappelle les arbres géants qui le remplissent. La chamane de la {link:horde}Horde{/link} {link:seereth-stonebreak}Seereth Stonebreak{/link} établit son camp près du val quand elle fut envoyée répondre aux cris de la terre, et c'est de sa lisière que le chemin part vers le nord-ouest jusqu'à la {link:windshear-crag}Combe des Cisailles{/link}, droit dans les griffes de la {link:venture-company}KapitalRisk{/link}.]=],
		},
	},
})

Translate("frFR", "webwinder-path", {
	title = "Sentier des Tisseuses",
	aliases = { "Canyon de Sishir" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Sentier des Tisseuses est la longue route qui traverse les vallées du sud des {link:stonetalon-mountains}Serres-Rocheuses{/link}, reliant la {link:sun-rock-retreat}Retraite de Roche-Soleil{/link} à {link:malaka-jin}Malaka'jin{/link} et aux {link:the-barrens}Tarides{/link}. Il tire son nom des araignées qui le hantent. Elles sont les plus nombreuses dans le Canyon de Sishir, à l'ouest de la route, où la grande araignée {link:besseleth}Besseleth{/link} et sa couvée ont fait un repaire tissé de toiles. La nuit, elles sortent chasser, et les voyageurs qui empruntent le sentier après la tombée du jour n'en atteignent pas toujours le bout. Même les trolls de Malaka'jin, qui craignent peu de chose, restent près de leurs feux quand le soleil est couché.]=],
		},
	},
})

Translate("frFR", "malaka-jin", {
	title = "Malaka'jin",
	sections = {
		{
			title = "Résumé",
			text = [=[Malaka'jin est un village troll au pied sud des {link:stonetalon-mountains}Serres-Rocheuses{/link}, là où la route monte depuis les {link:the-barrens}Tarides{/link}. Ses habitants sont des {link:darkspear-trolls}Darkspear{/link}, et ils ont prospéré ici grâce à la riche chasse des collines. Le village est connu pour ses potions de soin et pour ses sorciers-docteurs, avant tout {link:witch-doctor-jin-zil}Jin'Zil{/link}, qui garde trois elfes de la nuit captifs dans des cages à côté de sa hutte. Des araignées attaquent le camp la nuit, et ses chasseurs veulent s'en débarrasser. Le {link:grimtotem-post}Poste Totem sinistre{/link} se trouve non loin au nord.]=],
		},
	},
})

Translate("frFR", "boulderslide-ravine", {
	title = "Ravin des Eboulis",
	aliases = { "Caverne des Eboulis" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Ravin des Eboulis est une gorge profonde au sud des {link:stonetalon-mountains}Serres-Rocheuses{/link}, au sud-est de la {link:sun-rock-retreat}Retraite de Roche-Soleil{/link}. Une caverne s'ouvre dans sa paroi, et dans cette caverne, des {link:kobolds}kobolds{/link} menés par Gogger Stonepounder creusent frénétiquement pour trouver un cristal rare appelé résonite. Au fond de leurs tunnels, ils trouvèrent plus que du cristal. Dans une gangue de résonite gisait {link:goggeroc}Goggeroc{/link}, un terrestre endormi depuis des âges oubliés. Les chamans de Roche-Soleil comptent ce danger parmi les plus graves des montagnes.]=],
		},
	},
})

Translate("frFR", "grimtotem-post", {
	title = "Poste Totem sinistre",
	aliases = { "Camp Aparaje" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Poste Totem sinistre est un camp de guerre du {link:grimtotem-clan}clan Totem sinistre{/link} au sud-est des {link:stonetalon-mountains}Serres-Rocheuses{/link}, au-dessus de la route des {link:the-barrens}Tarides{/link}. C'est d'ici que {link:grundig-darkcloud}Grundig Darkcloud{/link} et ses brutes fondirent sur un village {link:tauren}tauren{/link} et tuèrent presque tous ses habitants. La jeune {link:kaya-flathoof}Kaya Flathoof{/link} fut ramenée au camp comme captive. Le camp Aparaje se trouve non loin. C'est là que Kaya demanda à être conduite quand elle fut libérée, car de là, elle connaissait le chemin du retour.]=],
		},
	},
})

Translate("frFR", "the-talondeep-path", {
	title = "La Perce des Serres",
	aliases = { "Perce des Serres" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Perce des Serres est un tunnel à travers les montagnes qui relie le nord-est des {link:stonetalon-mountains}Serres-Rocheuses{/link} au sud d'{link:ashenvale}Orneval{/link}, non loin du {link:mystral-lake}Lac Mystral{/link}. C'est la route des {link:night-elves}kaldorei{/link} qui descendent vers le pic, et de tout voyageur qui préfère ne pas traverser les {link:the-barrens}Tarides{/link}. À son débouché côté Serres-Rocheuses, au-dessus de la {link:windshear-crag}Combe des Cisailles{/link}, le chaman de la {link:horde}Horde{/link} {link:braug-dimspirit}Braug Dimspirit{/link} tient son camp et éprouve la sagesse de ceux qui viennent à lui.]=],
		},
	},
})

Translate("frFR", "keeper-albagorm", {
	title = "Gardien Albagorm",
	subtitle = "Gardien du Pic des Serres-Rocheuses",
	found = "Pic des Serres-Rocheuses",
	hint = [=[Montez à la couronne des montagnes et parlez au gardien qui veille sur elle.]=],
	allegiance = "Darnassus · Druides du pic",
	aliases = { "Albagorm" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le gardien Albagorm est le protecteur {link:night-elves}kaldorei{/link} du {link:stonetalon-peak}Pic des Serres-Rocheuses{/link}. Il se dit protecteur des esprits de la forêt, et depuis le sommet il a vu les forêts en contrebas tomber sous le feu et la scie. Il n'a pas pleuré. Il a fait des plans. Sa réponse à la ruine du {link:the-charred-vale}Val calciné{/link} n'est pas la seule vengeance, mais la repousse, et il entend revoir le val vert.]=],
		},
		{
			title = "Importance",
			text = [=[Albagorm est la voix de l'ancienne foi {link:night-elves}kaldorei{/link} aux {link:stonetalon-mountains}Serres-Rocheuses{/link}. Il voit la terre comme un seul être vivant, et les gobelins et les harpies comme des blessures infligées à ce corps. Il sait aussi que les druides du pic ne peuvent la guérir seuls, et il cherche de l'aide jusqu'auprès des druides de {link:feralas}Féralas{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il veille sur le {link:stonetalon-peak}Pic des Serres-Rocheuses{/link} et sur les druides qui y vivent.
• Il envoie des voyageurs contre les harpies Rouges-furies, qui interdisent aux druides l'accès au {link:the-charred-vale}Val calciné{/link}.
• Il cherche l'aide du druide {link:falfindel-waywarder}Falfindel Waywarder{/link} de {link:feralas}Féralas{/link}, qui peut appeler de grands esprits de la forêt dans le val dévasté.
• Il reçoit les voyageurs que les esprits de la forêt lui envoient d'{link:ashenvale}Orneval{/link}.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique ne dit depuis combien de temps Albagorm garde le pic, ni ce qu'il faisait avant l'arrivée des gobelins.]=],
		},
	},
	chapters = {
		{
			title = "Le saccage du val",
			hint = "Répondez à l'appel du gardien pour nettoyer le Val calciné.",
			text = [=[Albagorm nomme sans détour la cause de la ruine du {link:the-charred-vale}Val calciné{/link} : la cupidité. Les machines des gobelins ont mis le feu au val, et maintenant les harpies Rouges-furies perchent dans ses cendres et chassent tout druide qui vient replanter. Avant que le val puisse guérir, il faut en chasser les harpies. Il ne demande aucune pitié pour elles.]=],
		},
		{
			title = "Un appel à Féralas",
			hint = "Portez la supplique du gardien loin vers le sud.",
			text = [=[Les harpies ont été brisées, mais elles reviendront. Albagorm sait que les graines seules ne peuvent les devancer. Il fait porter un message à travers toute l'étendue de {link:kalimdor}Kalimdor{/link} au druide {link:falfindel-waywarder}Falfindel Waywarder{/link}, à l'orée des forêts de {link:feralas}Féralas{/link}. Le gardien croit que seuls les grands esprits de la forêt peuvent reconquérir le val à temps.]=],
		},
	},
	mentions = {
		{
			text = [=[Voyage vers le {link:stonetalon-peak}Pic des Serres-Rocheuses{/link}, envoyé par le druide {link:faldreas-goeth-shael}Faldreas{/link}]=],
		},
		{ text = "Reconquérir le {link:the-charred-vale}Val calciné{/link}" },
		{
			text = [=[Reconquérir le {link:the-charred-vale}Val calciné{/link}, l'appel à {link:falfindel-waywarder}Falfindel{/link}]=],
		},
	},
	bonds = {
		{ id = "kaela-shadowspear", name = "Kaela Shadowspear", note = "combat le même ennemi dans la Combe des Cisailles" },
		{ id = "bloodfury-ripper", name = "Bloodfury Ripper", note = "reine des harpies qu'il veut chasser" },
		{ id = "braelyn-firehand", name = "Braelyn Firehand", note = "traque les druides de son pic" },
	},
})

Translate("frFR", "kaela-shadowspear", {
	title = "Kaela Shadowspear",
	subtitle = "Sentinelle des Serres-Rocheuses",
	found = "Le belvédère à la lisière ouest de la Combe des Cisailles",
	hint = [=[Trouvez la Sentinelle qui surveille la vallée menant à la Combe des Cisailles.]=],
	allegiance = "Sentinelles · Darnassus",
	aliases = { "Kaela" },
	sections = {
		{
			title = "Résumé",
			text = [=[Kaela Shadowspear est une Sentinelle d'{link:ashenvale}Orneval{/link}, envoyée aux {link:stonetalon-mountains}Serres-Rocheuses{/link} pour découvrir ce qui arrivait à la terre. Elle trouva les forêts de la {link:windshear-crag}Combe des Cisailles{/link} abattues et le {link:the-charred-vale}Val calciné{/link} en flammes. Elle est restée depuis, combattant les gobelins depuis un belvédère au-dessus de la combe. À ses côtés travaille le mage {link:gnomes}gnome{/link} {link:gaxim-rustfizzle}Gaxim Rustfizzle{/link}, une association que son propre peuple a du mal à croire.]=],
		},
		{
			title = "Importance",
			text = [=[Kaela est la preuve de la gravité de la situation. Une {link:night-elves}elfe de la nuit{/link} et un {link:gnomes}gnome{/link}, une Sentinelle qui se méfie des arcanes et un mage qui s'en délecte, ont uni leurs forces contre un ennemi commun. Kaela demande aux autres de ne pas juger {link:gaxim-rustfizzle}Gaxim{/link} trop vite. Qu'elle puisse seulement le dire est un signe des temps.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle fut envoyée aux {link:stonetalon-mountains}Serres-Rocheuses{/link} sur ordre de la Sentinelle Wolfrunner, et son amie {link:sentinel-thenysil}Tara Thenysil{/link}, à {link:astranaar}Astranaar{/link}, attend depuis longtemps de ses nouvelles.
• Elle combat la destruction des forêts par la {link:venture-company}KapitalRisk{/link}.
• Elle traque les esprits ardents libérés dans le {link:the-charred-vale}Val calciné{/link}.
• Elle prélève des éclats de métal sur les tréants blessés du val, afin que {link:gaxim-rustfizzle}Gaxim{/link} puisse apprendre comment ils furent corrompus.]=],
		},
	},
	chapters = {
		{
			title = "Le val en pleurs",
			hint = [=[Aidez la Sentinelle contre les esprits ardents du Val calciné.]=],
			text = [=[La première fois que Kaela vit le {link:the-charred-vale}Val calciné{/link}, elle faillit pleurer. Les gobelins n'avaient pas seulement brûlé les arbres. Dans leur folie, ils avaient libéré des élémentaires de flamme, de pierre et de rage, et tant que ces esprits arpentent le val, dit-elle, la terre n'a aucune chance de voir le sourire d'Élune.]=],
		},
		{
			title = "Nouvelles pour Astranaar",
			hint = "Rapportez les nouvelles de la Sentinelle en Orneval.",
			text = [=[Quand les gobelins ont reçu un coup, Kaela envoie enfin un message au nord : elle et {link:gaxim-rustfizzle}Gaxim{/link} sont vivants, et ils sont en bonne voie pour arrêter la {link:venture-company}KapitalRisk{/link}. À {link:astranaar}Astranaar{/link}, {link:sentinel-thenysil}Tara Thenysil{/link} apprend la nouvelle et s'en réjouit, et pas seulement pour Kaela. Elle se surprend à se réjouir aussi pour le {link:gnomes}gnome{/link}.]=],
		},
	},
	mentions = {
		{
			text = [=[En faction aux {link:stonetalon-mountains}Serres-Rocheuses{/link}, envoyé par la {link:sentinel-thenysil}Sentinelle Thenysil{/link}]=],
		},
		{
			text = [=[En faction aux {link:stonetalon-mountains}Serres-Rocheuses{/link}]=],
		},
		{ text = "Esprits enragés" },
		{ text = "Anciens blessés" },
		{
			text = [=[Les nouvelles de Kaela, apportées de la part de {link:gaxim-rustfizzle}Gaxim{/link}]=],
		},
		{
			text = [=[Nouvelles pour la {link:sentinel-thenysil}Sentinelle Thenysil{/link}]=],
		},
	},
	bonds = {
		{ id = "gaxim-rustfizzle", name = "Gaxim Rustfizzle", note = "son improbable associé" },
		{ id = "keeper-albagorm", name = "Gardien Albagorm", note = "garde le pic au-dessus d'elle" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "entend parler de sa mission" },
	},
})

Translate("frFR", "gaxim-rustfizzle", {
	title = "Gaxim Rustfizzle",
	subtitle = "Gnome de l'Assemblée éclairée",
	found = [=[Aux côtés de Kaela Shadowspear, à la lisière ouest de la Combe des Cisailles]=],
	hint = [=[Cherchez le gnome qui travaille aux côtés de la Sentinelle au-dessus de la Combe des Cisailles.]=],
	allegiance = [=[Exilés de Gnomeregan · Assemblée éclairée des sciences de l'arcanologie, de l'alchimie et de l'ingénierie]=],
	aliases = { "Gaxim" },
	sections = {
		{
			title = "Résumé",
			text = [=[Gaxim Rustfizzle est un mage et bricoleur {link:gnomes}gnome{/link}, et un fier membre d'une société savante au nom très long : l'Assemblée éclairée des sciences de l'arcanologie, de l'alchimie et de l'ingénierie. Il vint aux {link:stonetalon-mountains}Serres-Rocheuses{/link} avec la Sentinelle {link:kaela-shadowspear}Kaela Shadowspear{/link}. Il croit, de toute la force de son petit corps, qu'un mélange de magie, de mixtures et de mécanismes peut sauver les forêts des elfes de la nuit. Il entend le prouver avec des explosifs.]=],
		},
		{
			title = "Importance",
			text = [=[Gaxim incarne une idée à laquelle les {link:night-elves}kaldorei{/link} résistent depuis longtemps : la magie et l'artisanat, bien employés, peuvent servir la forêt au lieu de lui nuire. Il dit ouvertement que les elfes de la nuit ont besoin de la magie, et que le monde en a besoin. Sa guerre contre la {link:venture-company}KapitalRisk{/link} est son argument.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il repousse les gobelins par des détonations bien placées le long des bords des montagnes.
• Il conçoit des explosifs à distance à partir d'un composé rare, le NG-5, et d'un sort de message.
• Il prépare deux raids contre la {link:venture-company}KapitalRisk{/link}, l'un pour ses plans techniques et l'autre pour ses lettres.
• Il étudie les éclats de métal tirés des tréants corrompus du {link:the-charred-vale}Val calciné{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Une détonation à distance",
			hint = [=[Rassemblez ce dont le gnome a besoin pour son engin explosif.]=],
			text = [=[Le plan de Gaxim exigeait deux choses qu'il ne pouvait fabriquer lui-même. La première était le Nitromirglyceronium, ou NG-5, que seul son ancien collègue Lomac Gearstrip de {link:tinker-town}Tinker Town{/link} savait préparer. La seconde était un sort permettant de déclencher une charge de loin, et pour cela il écrivit à Collin Mauren, un mage de {link:stormwind-city}Stormwind{/link}. Quand il eut les deux en main, Gaxim déclara son engin parfait. Les chariots de dynamite étaient prêts.]=],
		},
		{
			title = "Opérations secrètes",
			hint = "Exécutez les plans du gnome contre la KapitalRisk.",
			text = [=[Les explosions n'avaient jamais été le but, insistait Gaxim. Elles étaient une diversion. Pendant que les gobelins couraient en tous sens, pris de panique, le vrai trésor fut pris : les plans techniques de la scierie au sud du {link:cragpool-lake}Lac de la Combe{/link}, et les lettres privées de la compagnie. Avec eux, Gaxim espérait trouver les faiblesses des machines gobelines, et peut-être aussi emprunter quelques-uns de leurs modèles.]=],
		},
	},
	mentions = {
		{ text = "Le répit d'un {link:gnomes}gnome{/link}" },
		{ text = "Un ancien collègue" },
		{ text = "Incompétence + produits chimiques = amusement" },
		{ text = "Un parchemin de Mauren" },
		{ text = "Livraison spéciale pour Gaxim" },
		{ text = "Opérations secrètes - Alpha" },
		{ text = "Opérations secrètes - Bêta" },
		{ text = "Les nouvelles de {link:kaela-shadowspear}Kaela{/link}" },
		{
			text = [=[L'accueil de {link:tyrande-whisperwind}Tyrande{/link}, après les raids]=],
		},
		{ text = "La tâche de Castpipe" },
	},
	bonds = {
		{ id = "kaela-shadowspear", name = "Kaela Shadowspear", note = "son associée aux Serres-Rocheuses" },
		{ id = "gerenzo-wrenchwhistle", name = "Gerenzo Wrenchwhistle", note = "un gnome dans l'autre camp" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "honore ceux qui aident sa mission" },
	},
})

Translate("frFR", "seereth-stonebreak", {
	title = "Seereth Stonebreak",
	subtitle = "Chamane de la Horde",
	found = [=[Le lieu de l'Honneur, à la frontière des Tarides et des Serres-Rocheuses]=],
	hint = [=[Trouvez la chamane qui campe sur la route de l'ouest, là où les Tarides montent vers les Serres-Rocheuses.]=],
	allegiance = "Horde · Orgrimmar",
	aliases = { "Seereth" },
	sections = {
		{
			title = "Résumé",
			text = [=[Seereth Stonebreak est une jeune chamane de la {link:horde}Horde{/link}, envoyée d'{link:orgrimmar}Orgrimmar{/link} pour répondre aux cris des {link:stonetalon-mountains}Serres-Rocheuses{/link}. Le vieux prophète {link:zor-lonetree}Zor Lonetree{/link} avait entendu que la terre souffrait. C'est Seereth qu'il envoya découvrir pourquoi. Elle trouva les gobelins de la {link:venture-company}KapitalRisk{/link} en train de couper et de brûler les forêts, et elle a établi son camp à la frontière depuis, rassemblant toute l'aide qu'elle peut trouver.]=],
		},
		{
			title = "Importance",
			text = [=[Seereth est la première réponse de la {link:horde}Horde{/link} au sort des {link:stonetalon-mountains}Serres-Rocheuses{/link}. C'est sa parole qui porta l'affaire devant les anciens taurens, et à travers eux jusqu'à {link:magatha-grimtotem}Magatha Grimtotem{/link} et aux {link:forsaken}Réprouvés{/link}. Ce qui avait commencé comme la vision d'une chamane devint un complot d'empoisonnement.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle signale à {link:orgrimmar}Orgrimmar{/link} la grande déforestation des {link:stonetalon-mountains}Serres-Rocheuses{/link} et demande de l'aide.
• Elle envoie des guerriers dans la {link:windshear-crag}Combe des Cisailles{/link} contre les gobelins et leurs serviteurs.
• Elle rêve des deux déchiqueteuses qui abattent les arbres de la combe.
• Elle cherche le conseil des anciens taurens, et de {link:magatha-grimtotem}Magatha{/link} avant tout.]=],
		},
	},
	chapters = {
		{
			title = "La voix de la terre",
			hint = [=[Répondez à l'appel du prophète à la frontière des Serres-Rocheuses.]=],
			text = [=[Seereth entend les esprits des {link:stonetalon-mountains}Serres-Rocheuses{/link} comme une chamane les entend, et ce qu'elle entend, c'est la rage. Les gobelins ont pris les arbres, et les esprits sont presque aveuglés par la douleur. Elle ne conseille pas la patience. Elle demande que l'on parle à la {link:venture-company}KapitalRisk{/link} le seul langage qu'elle comprenne.]=],
		},
		{
			title = "XT:4 et XT:9",
			hint = "Faites taire les machines de la vision de Seereth.",
			text = [=[La plupart des murmures des esprits lui échappent, mais une vision lui vint clairement : deux machines à forme humaine dans la {link:windshear-crag}Combe des Cisailles{/link}, abattant des arbres à une vitesse impossible, marquées des signes XT:4 et XT:9. Quand toutes deux furent détruites, bien des esprits furent apaisés. Seereth ne se réjouit pas. Si les gobelins ne quittaient pas les montagnes, avertit-elle, le pire restait à venir.]=],
		},
	},
	mentions = {
		{
			text = [=[Les esprits des {link:stonetalon-mountains}Serres-Rocheuses{/link}]=],
		},
		{ text = "Les envahisseurs gobelins" },
		{ text = "Les machines déchiqueteuses" },
		{ text = "La Doyenne" },
	},
	bonds = {
		{ id = "zor-lonetree", name = "Zor Lonetree", note = "l'envoya aux Serres-Rocheuses" },
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "l'ancienne qu'elle fit prévenir" },
		{ id = "makaba-flathoof", name = "Makaba Flathoof", note = "partage son camp" },
	},
})

Translate("frFR", "maggran-earthbinder", {
	title = "Maggran Earthbinder",
	subtitle = "Défenseur de Roche-Soleil",
	found = "Retraite de Roche-Soleil",
	hint = [=[Parlez au tauren qui commande la défense de la Retraite de Roche-Soleil.]=],
	allegiance = "Horde · Thunder Bluff",
	aliases = { "Maggran" },
	sections = {
		{
			title = "Résumé",
			text = [=[Maggran Earthbinder est un guerrier {link:tauren}tauren{/link} qui assure la défense de la {link:sun-rock-retreat}Retraite de Roche-Soleil{/link}. Il croit que son peuple est le protecteur de ces terres, et il prend ce devoir à cœur. Il porte une cicatrice laissée par les crochets de l'araignée {link:besseleth}Besseleth{/link}, et il fait la guerre aux harpies Rouges-furies depuis si longtemps qu'il ne sait pas trop ce qu'il fera sans elles.]=],
		},
		{
			title = "Importance",
			text = [=[Maggran est la main de la {link:horde}Horde{/link} aux {link:stonetalon-mountains}Serres-Rocheuses{/link}. Là où les chamans guérissent, il combat, et les primes qu'il affiche donnent la mesure de chaque danger des montagnes.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il affiche des primes sur les harpies Rouges-furies et sur leur reine.
• Il met à prix la tête de {link:besseleth}Besseleth{/link}, l'araignée du {link:webwinder-path}Canyon de Sishir{/link}, qui le blessa autrefois.
• Il envoie un guerrier de réserve relever Grish Longrunner à la Grande élévation, afin que le jeune garde puisse rendre visite à sa famille.
• Il envoie les pierres de soleil des harpies à {link:mor-rogal}Mor'rogal{/link}, qui sait quoi en faire.]=],
		},
	},
	chapters = {
		{
			title = "Le fléau des harpies",
			hint = [=[Répondez à l'appel de Maggran contre les harpies Rouges-furies.]=],
			text = [=[Maggran ne voit pas les Rouges-furies comme un trouble local. Pour lui, elles sont la source des harpies qui infestent tout {link:kalimdor}Kalimdor{/link}, une maladie qui se répand depuis le {link:the-charred-vale}Val calciné{/link} et prend au piège les innocents dans ses limites. Réduire leur nombre ne suffit pas. Le remède, dit-il, c'est leur reine.]=],
		},
		{
			title = "Après l'Éventreuse",
			hint = "Abattez la reine des harpies Rouges-furies.",
			text = [=[Quand la {link:bloodfury-ripper}Bloodfury Ripper{/link} fut tuée, la colère quitta Maggran. Cela le surprit. Pendant des années, le mal voisin de sa terre avait gardé ses pensées aiguisées, et maintenant elles étaient calmes. Peut-être, dit-il, était-ce une bonne chose. Peut-être pourrait-il désormais se tourner vers le bien, comme un {link:tauren}tauren{/link} le doit.]=],
		},
		{
			title = "La vieille prédatrice",
			hint = "Mettez fin à la menace du Canyon de Sishir.",
			text = [=[{link:besseleth}Besseleth{/link} est une vieille chasseresse de ces collines. Elle surprit un jour Maggran sur le {link:webwinder-path}Sentier des Tisseuses{/link}, de nuit, et il lui échappa de justesse. Maintenant qu'elle n'est plus, il espère que davantage de voyageurs viendront à {link:sun-rock-retreat}Roche-Soleil{/link} sans craindre ce qui attend dans le noir.]=],
		},
	},
	mentions = {
		{ text = "La menace des harpies" },
		{ text = "La lignée des Rouges-furies" },
		{
			text = [=[Arachnophobie, d'après un panneau d'avertissement dans le {link:webwinder-path}Canyon de Sishir{/link}]=],
		},
		{ text = "Appel aux réserves" },
		{ text = "Colifichets des Rouges-furies" },
	},
	bonds = {
		{ id = "bloodfury-ripper", name = "Bloodfury Ripper", note = "la reine dont il voulait la mort" },
		{ id = "besseleth", name = "Besseleth", note = "lui laissa une cicatrice" },
		{ id = "mor-rogal", name = "Mor'rogal", note = "reçoit les pierres de soleil" },
		{ id = "tammra-windfield", name = "Tammra Windfield", note = "sert Roche-Soleil avec lui" },
	},
})

Translate("frFR", "tammra-windfield", {
	title = "Tammra Windfield",
	subtitle = "Guérisseuse de la terre",
	found = "Retraite de Roche-Soleil",
	hint = [=[Cherchez la taurène de Roche-Soleil qui s'efforce de guérir la terre avec les bénédictions de la Terre-Mère.]=],
	allegiance = "Horde · Thunder Bluff",
	aliases = { "Tammra" },
	sections = {
		{
			title = "Résumé",
			text = [=[Tammra Windfield est une taurène de la {link:sun-rock-retreat}Retraite de Roche-Soleil{/link} qui s'est donné pour tâche de guérir les {link:stonetalon-mountains}Serres-Rocheuses{/link}. Elle croit que seules les bénédictions de la Terre-Mère peuvent guérir les blessures laissées par la cupidité et la guerre. Elle travaille avec des graines, des chants et de la patience. Elle est aussi la tante de {link:kaya-flathoof}Kaya Flathoof{/link}, une jeune fille que {link:grimtotem-clan}les Totem sinistre{/link} enlevèrent et que sa famille croyait morte.]=],
		},
		{
			title = "Importance",
			text = [=[Tammra est l'autre visage de la {link:horde}Horde{/link} aux {link:stonetalon-mountains}Serres-Rocheuses{/link}. Là où les guerriers de {link:sun-rock-retreat}Roche-Soleil{/link} déciment les harpies, elle plante. Elle espère qu'un jour la {link:venture-company}KapitalRisk{/link} remballera ses scies, que les esprits du feu s'apaiseront et que la terre elle-même chassera les harpies.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle récolte des graines de Gaïa au {link:mirkfallon-lake}Lac Mirkfallon{/link} et les imprègne de pouvoir chamanique.
• Elle fait planter les graines enchantées dans les monticules fertiles du {link:the-charred-vale}Val calciné{/link}.
• Elle apprend la nouvelle du sauvetage de sa nièce, arrachée aux Totem sinistre.]=],
		},
	},
	chapters = {
		{
			title = "Le cycle de la renaissance",
			hint = "Apportez à Tammra les graines du Lac Mirkfallon.",
			text = [=[Les graines de Gaïa ne poussent qu'au bord de l'eau, au {link:mirkfallon-lake}Lac Mirkfallon{/link}. Tammra les prend dans ses mains et chante sur elles, et les graines s'éveillent. Seuls ceux qui sont purs et sincères, dit-elle, peuvent guérir la terre. Elle ne demande rien de plus aux graines que de pousser.]=],
		},
		{
			title = "Une vie nouvelle dans les cendres",
			hint = "Plantez les graines enchantées au cœur de la dévastation.",
			text = [=[Les graines furent plantées au centre de la ruine, dans le {link:the-charred-vale}Val calciné{/link}, parmi les harpies et les esprits ardents. Elles résisteront à la corruption et offriront une prise à d'autres formes de vie. Avec le temps, croit Tammra, elles rendront aux {link:stonetalon-mountains}Serres-Rocheuses{/link} leur forêt. Ce ne sera pas pour bientôt. Elle ne s'y attend pas.]=],
		},
		{
			title = "Kaya est vivante",
			hint = [=[Apportez à Tammra la nouvelle qu'elle pensait ne jamais entendre.]=],
			text = [=[Après que {link:grimtotem-clan}les Totem sinistre{/link} eurent détruit le village des siens, Tammra crut sa nièce {link:kaya-flathoof}Kaya{/link} perdue. Quand vint la nouvelle que la jeune fille avait été libérée et qu'elle vivait, Tammra ne put que rendre grâce.]=],
		},
	},
	mentions = {
		{ text = "Le cycle de la renaissance" },
		{ text = "Une vie nouvelle" },
		{ text = "{link:kaya-flathoof}Kaya{/link} est vivante" },
	},
	bonds = {
		{ id = "kaya-flathoof", name = "Kaya Flathoof", note = "sa nièce" },
		{ id = "makaba-flathoof", name = "Makaba Flathoof", note = "le père de Kaya" },
		{ id = "maggran-earthbinder", name = "Maggran Earthbinder", note = "sert Roche-Soleil avec elle" },
	},
})

Translate("frFR", "mor-rogal", {
	title = "Mor'rogal",
	subtitle = "Voyant de Roche-Soleil",
	found = "Les collines au-dessus de la Retraite de Roche-Soleil",
	hint = [=[Montez dans les collines au-dessus de Roche-Soleil et parlez au tauren qui sent la tension dans l'air.]=],
	allegiance = "Horde · Thunder Bluff",
	sections = {
		{
			title = "Résumé",
			text = [=[Mor'rogal est un chaman {link:tauren}tauren{/link} qui se tient dans les collines au-dessus de la {link:sun-rock-retreat}Retraite de Roche-Soleil{/link}. Il sent quand quelque chose ne va pas dans la terre. Ces derniers temps, il l'a senti fortement. Le trouble qu'il percevait ne venait ni des gobelins ni des harpies, mais de quelque chose de profond sous les montagnes, là où les kobolds du {link:boulderslide-ravine}Ravin des Eboulis{/link} avaient creusé.]=],
		},
		{
			title = "Importance",
			text = [=[Mor'rogal découvrit l'une des plus graves menaces des {link:stonetalon-mountains}Serres-Rocheuses{/link} : un terrestre endormi, une créature des titans, enfoui dans la résonite sous le ravin. S'il s'était réveillé en pleine force, croyait-il, toutes les Serres-Rocheuses auraient été perdues.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoie des chercheurs dans la caverne du {link:boulderslide-ravine}Ravin des Eboulis{/link} pour découvrir ce que les kobolds extraient.
• Il reconnaît la magie des terrestres dans la résonite grâce à une vieille légende.
• Il enchante la résonite pour briser la gangue qui renfermait le terrestre {link:goggeroc}Goggeroc{/link}.
• Il trouve un usage aux pierres de soleil dorées que les harpies amassent.]=],
		},
	},
	chapters = {
		{
			title = "Le cristal des profondeurs",
			hint = [=[Découvrez ce que les kobolds cherchent dans le Ravin des Eboulis.]=],
			text = [=[Les échantillons de minerai revinrent de la caverne, et Mor'rogal les tourna dans ses mains jusqu'à ce qu'il se souvienne. La résonite porte une trace de la magie des terrestres. Les légendes disent que les terrestres furent créés par les titans pour façonner la terre elle-même. Si les kobolds avaient creusé assez profond pour trouver de la résonite, ils avaient creusé assez profond pour trouver un terrestre.]=],
		},
		{
			title = "Le réveil du terrestre",
			hint = [=[Réveillez le dormeur sous le ravin avant qu'il ne se réveille de lui-même.]=],
			text = [=[Mor'rogal ne pouvait empêcher {link:goggeroc}Goggeroc{/link} de se réveiller. Il choisit de le réveiller le premier, tant qu'il était affaibli par son long sommeil. Avec un cristal enchanté, la gangue fut brisée, et le terrestre fut tué avant que sa force ne revienne. Mor'rogal qualifia cet acte de dette que tout {link:kalimdor}Kalimdor{/link} aurait envers ceux qui l'avaient accompli.]=],
		},
	},
	mentions = {
		{ text = "Le {link:boulderslide-ravine}Ravin des Eboulis{/link}" },
		{ text = "Le réveil du terrestre" },
		{
			text = [=[Colifichets des Rouges-furies, envoyés par {link:maggran-earthbinder}Maggran{/link}]=],
		},
	},
	bonds = {
		{ id = "goggeroc", name = "Goggeroc", note = "le dormeur qu'il craignait" },
		{ id = "maggran-earthbinder", name = "Maggran Earthbinder", note = "lui envoie des pierres de soleil" },
	},
})

Translate("frFR", "braelyn-firehand", {
	title = "Braelyn Firehand",
	subtitle = "Servante d'un maître caché",
	found = "Retraite de Roche-Soleil",
	hint = [=[Cherchez l'étrangère de Roche-Soleil qui hait les druides du pic.]=],
	allegiance = "Inconnue · Un maître à Jaedenar",
	aliases = { "Braelyn" },
	sections = {
		{
			title = "Résumé",
			text = [=[Braelyn Firehand vit parmi la {link:horde}Horde{/link} à la {link:sun-rock-retreat}Retraite de Roche-Soleil{/link}, mais elle n'est pas une amie de la foi des taurens. Elle hait les druides du {link:stonetalon-peak}Pic des Serres-Rocheuses{/link}, qui selon ses mots étouffent le flux de la magie à travers les montagnes. Elle fut envoyée ici par un maître qui attend à {link:jaedenar}Jaedenar{/link}, loin au nord, et elle ne peut revenir tant que son œuvre n'est pas accomplie. Elle parle de l'époque d'{link:azshara}Azshara{/link} comme si elle s'en souvenait.]=],
		},
		{
			title = "Importance",
			text = [=[Braelyn est le fil de quelque chose d'ancien et de sombre aux {link:stonetalon-mountains}Serres-Rocheuses{/link}. Elle appelle le temple en ruine du pic « notre » temple d'{link:azshara}Azshara{/link}. Elle connut {link:keeper-ordanus}Ordanus{/link}, un fils de Cénarius, il y a longtemps, et elle dit qu'il se plaçait au-dessus même des Bien-nés. Quoi qu'elle soit, elle a faim de magie comme d'autres ont faim de pain.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle cherche la mort des druides cénariens et des enfants de Cénarius sur le pic.
• Elle traque {link:keeper-ordanus}Ordanus{/link}, que les druides ont emmené en secret en {link:ashenvale}Orneval{/link}.
• Elle arrache les secrets de l'antre des Serres à un druide capturé.]=],
		},
		{
			title = "Non consigné",
			text = [=[Le nom de son maître n'est pas écrit. Il n'est pas écrit non plus pourquoi la {link:horde}Horde{/link} la laisse vivre à {link:sun-rock-retreat}Roche-Soleil{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Un puits plein de trous",
			hint = [=[Aidez l'ensorceleuse à desserrer l'emprise des druides sur les montagnes.]=],
			text = [=[Aux {link:stonetalon-mountains}Serres-Rocheuses{/link}, dit Braelyn, puiser dans la magie revient à puiser de l'eau avec un seau percé. Quand les druides et les enfants de Cénarius tombèrent, elle sentit le flux revenir, doux et impétueux. Les {link:night-elves}kaldorei{/link}, dit-elle, sont fous de le dédaigner.]=],
		},
		{
			title = "La tête d'Ordanus",
			hint = "Trouvez le fils de Cénarius que les druides lui ont caché.",
			text = [=[Par sa vision, Braelyn le trouva : {link:keeper-ordanus}Ordanus{/link}, l'un des fils aînés du dieu de la forêt, caché au sommet d'un grand arbre à {link:raynewood-retreat}Raynewood{/link}, en {link:ashenvale}Orneval{/link}. Les druides l'avaient emmené du pic avant qu'elle ne puisse l'atteindre. Quand on lui apporta sa tête, elle la regarda sans pitié. Sa tête, dit-elle, ne s'élevait plus aussi haut.]=],
		},
		{
			title = "Le trésor de l'antre",
			hint = "Suivez le secret que Braelyn a arraché à un druide.",
			text = [=[Les druides de l'antre des Serres avaient construit une énigme minutieuse de clés pour garder leurs trésors. Braelyn en avait arraché le secret à l'un d'eux : une clé cachée dans une lanterne, trois caches, et un trésor au cœur de l'antre.]=],
		},
	},
	mentions = {
		{ text = "L'héritage de Cénarius" },
		{ text = "{link:keeper-ordanus}Ordanus{/link}" },
		{ text = "L'Antre" },
	},
	bonds = {
		{ id = "keeper-albagorm", name = "Gardien Albagorm", note = "garde le pic qu'elle méprise" },
	},
})

Translate("frFR", "witch-doctor-jin-zil", {
	title = "Sorcier-docteur Jin'Zil",
	subtitle = "Sorcier-docteur de Malaka'jin",
	found = "Sa hutte à Malaka'jin",
	hint = [=[Trouvez le sorcier-docteur de Malaka'jin qui garde trois cages à côté de sa hutte.]=],
	allegiance = "Horde · Trolls Darkspear",
	aliases = { "Jin'Zil" },
	sections = {
		{
			title = "Résumé",
			text = [=[Jin'Zil est un sorcier-docteur troll de {link:malaka-jin}Malaka'jin{/link}. Il est jovial, cruel et vieux dans les voies de son art. À côté de sa hutte se dressent trois cages, et dans chaque cage se trouve un {link:night-elves}elfe de la nuit{/link}. Il les appelle ses petits amis, et il entend leur préparer un avant-goût de ce qu'ils appellent la magie de la forêt.]=],
		},
		{
			title = "Importance",
			text = [=[Jin'Zil rappelle que la guerre entre la {link:horde}Horde{/link} et les {link:night-elves}kaldorei{/link} ne se livre pas seulement en {link:ashenvale}Orneval{/link}. Il est aussi un lien avec des temps plus anciens. Il se souvient du temps où son ami Rokhan partit avec un mok'nathal sauvage tuer la sœur aînée de la {link:harpies}harpie{/link} Serena Bloodfeather.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il garde trois prisonniers elfes de la nuit en cage à {link:malaka-jin}Malaka'jin{/link}.
• Il prépare pour ses captifs un breuvage de sève, de moustaches, d'yeux et d'écaille de dragon féerique.
• Il apprend de son vieil ami Darsok que la dernière des Bloodfeather est morte.]=],
		},
	},
	chapters = {
		{
			title = "La magie de la forêt",
			hint = "Rassemblez les étranges ingrédients du sorcier-docteur.",
			text = [=[Pour son breuvage, Jin'Zil voulait de la sève des {link:stonetalon-mountains}Serres-Rocheuses{/link}, des moustaches de coureurs du crépuscule, les yeux des coursiers et l'écaille d'un dragon féerique. Beaucoup d'yeux, insistait-il ; il n'y en a jamais assez. Ce que le breuvage fit aux elfes dans les cages, il ne le dit pas. Il promit seulement qu'il les ferait se sentir chez eux.]=],
		},
		{
			title = "Une lettre des Tarides",
			hint = "Portez à Malaka'jin la lettre d'un vieil ami.",
			text = [=[Jin'Zil n'avait pas eu de nouvelles de Darsok depuis bien des années. La lettre lui apprit que Serena Bloodfeather était morte, la dernière de sa lignée. Elle lui rappela sa jeunesse, quand il avait vu Rokhan partir avec un chasseur mok'nathal pour tuer sa sœur aînée.]=],
		},
	},
	mentions = {
		{ text = "Lettre à Jin'Zil" },
		{ text = "La magie de la forêt de Jin'Zil" },
	},
	bonds = {
		{ id = "ken-zigla", name = "Ken'zigla", note = "brasse à Malaka'jin" },
		{ id = "xen-zilla", name = "Xen'Zilla", note = "du même village" },
	},
})

Translate("frFR", "ziz-fizziks", {
	title = "Ziz Fizziks",
	subtitle = "L'ingénieur qui changea de camp",
	found = "Un camp à la lisière ouest de la Combe des Cisailles",
	hint = [=[Trouvez l'ingénieur gobelin qui campe à la lisière ouest de la Combe des Cisailles.]=],
	allegiance = "Tinkers' Union · Cartel Gentepression",
	aliases = { "Ziz" },
	sections = {
		{
			title = "Résumé",
			text = [=[Ziz Fizziks était autrefois l'ingénieur en chef des travaux de la {link:venture-company}KapitalRisk{/link} aux {link:stonetalon-mountains}Serres-Rocheuses{/link}. Puis la compagnie engagea un {link:gnomes}gnome{/link}, {link:gerenzo-wrenchwhistle}Gerenzo Wrenchwhistle{/link}, et lui confia la direction. Ziz fut renvoyé. Il en fut si offensé qu'il supplia Sputtervalve de {link:ratchet}Ratchet{/link} de lui trouver du travail auprès de la Tinkers' Union, et il espionne maintenant ses anciens maîtres depuis un camp à la lisière de la combe.]=],
		},
		{
			title = "Importance",
			text = [=[Ziz montre que la loyauté d'un gobelin va exactement aussi loin que sa paie. Il déteste ce que la compagnie a fait aux montagnes, du moins le dit-il. Il déteste bien plus encore qu'on lui ait préféré un {link:gnomes}gnome{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il laissa un agent, {link:piznik}Piznik{/link}, à l'intérieur de la mine de la compagnie pour recueillir des secrets.
• Il vole les plans du Super Reaper 6000, la grande machine à abattre les arbres de la compagnie.
• Il envoie les documents et les manuels de la compagnie à Sputtervalve, à {link:ratchet}Ratchet{/link}.
• Il met à prix la tête de {link:gerenzo-wrenchwhistle}Gerenzo Wrenchwhistle{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Le Super Reaper",
			hint = [=[Aidez l'ingénieur à voler les plans de la grande machine de la compagnie.]=],
			text = [=[{link:venture-company}La KapitalRisk{/link} avait construit une énorme machine pour couper le bois, et Sputtervalve voulait ses plans. Ziz ne pouvait aller les chercher lui-même, car {link:gerenzo-wrenchwhistle}Gerenzo{/link} voulait le faire tuer à vue. Quand les plans arrivèrent entre ses mains, il put à peine les lire. Il se demanda à voix haute comment les gnomes avaient jamais réussi à inventer la roue.]=],
		},
		{
			title = "Le bras mécanique",
			hint = "Abattez le gnome qui a pris la place de Ziz.",
			text = [=[Ziz avait rencontré {link:gerenzo-wrenchwhistle}Gerenzo{/link} une fois, et il n'avait oublié ni la chair pourrissante ni les engrenages. Il n'aurait jamais pu se frayer un chemin jusqu'à la tour du {link:gnomes}gnome{/link} lui-même. Quand on déposa devant lui le bras mécanique de Gerenzo, Ziz secoua la tête. Pourquoi couper un bras pour le remplacer, demanda-t-il, quand on pourrait simplement en ajouter un troisième ?]=],
		},
	},
	mentions = {
		{ text = "Ziz Fizziks, envoyé par Sputtervalve" },
		{ text = "Super Reaper 6000" },
		{ text = "Instructions supplémentaires" },
		{ text = "Les ordres de {link:gerenzo-wrenchwhistle}Gerenzo{/link}" },
		{
			text = [=[Instructions supplémentaires, au retour de {link:ratchet}Ratchet{/link}]=],
		},
		{ text = "{link:gerenzo-wrenchwhistle}Gerenzo Wrenchwhistle{/link}" },
	},
	bonds = {
		{ id = "piznik", name = "Piznik", note = "son agent dans la mine" },
		{ id = "gerenzo-wrenchwhistle", name = "Gerenzo Wrenchwhistle", note = "prit sa place" },
		{ id = "gazlowe", name = "Gazlowe", note = "gouverne le port où travaille son nouveau maître" },
	},
})

Translate("frFR", "gerenzo-wrenchwhistle", {
	title = "Gerenzo Wrenchwhistle",
	subtitle = "Surveillant de la KapitalRisk aux Serres-Rocheuses",
	found = [=[Haut au-dessus du Lac de la Combe, près de la grande roue à aubes]=],
	hint = [=[Affrontez le gnome qui surveille les travaux des gobelins depuis les hauteurs du Lac de la Combe.]=],
	allegiance = "La KapitalRisk",
	aliases = { "Gerenzo" },
	sections = {
		{
			title = "Résumé",
			text = [=[Gerenzo Wrenchwhistle est un {link:gnomes}gnome{/link} au service de la {link:venture-company}KapitalRisk{/link}, et le maître de ses travaux aux {link:stonetalon-mountains}Serres-Rocheuses{/link}. Les gobelins l'engagèrent, à la fureur de leurs propres ingénieurs, et il prit la direction de toute l'opération. Il n'est pas agréable à regarder. Sa chair semble pourrir, il a greffé du métal et des engrenages sur son corps, et il a remplacé certains de ses membres par des machines.]=],
		},
		{
			title = "Importance",
			text = [=[Gerenzo est le plus étrange serviteur de la cupidité des gobelins : un {link:gnomes}gnome{/link} qui a livré son propre corps à la machine. Depuis son perchoir au-dessus du {link:cragpool-lake}Lac de la Combe{/link}, il mène la destruction de la {link:windshear-crag}Combe des Cisailles{/link}, et c'est sous ses ordres que la compagnie commença à extraire un étrange minerai vert doré.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il prit le commandement du chantier de la compagnie aux {link:stonetalon-mountains}Serres-Rocheuses{/link} et renvoya {link:ziz-fizziks}Ziz Fizziks{/link}.
• Il ordonna d'extraire de grandes quantités d'un minerai vert doré dans la Mine des {link:windshear-crag}Cisailles{/link}.
• Il a juré de tuer Ziz à vue.
• Il a remplacé son propre bras par un bras mécanique.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique ne dit d'où vient Gerenzo, comment il perdit ses membres, ni pourquoi un {link:gnomes}gnome{/link} servirait la {link:venture-company}KapitalRisk{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Le minerai vert doré",
			hint = "Découvrez ce que le gnome cherche à extraire.",
			text = [=[Personne sous les ordres de Gerenzo ne savait pourquoi il voulait autant de ce minerai vert doré. {link:piznik}Piznik{/link} fit sortir en contrebande un échantillon de la mine, et {link:ziz-fizziks}Ziz{/link} en envoya un morceau aux ingénieurs de Undermine, en gardant un peu pour lui. Ce qu'est le minerai, et ce que Gerenzo compte en faire, n'est pas écrit.]=],
		},
	},
	mentions = {
		{ text = "Les ordres de Gerenzo" },
		{ text = "Gerenzo Wrenchwhistle" },
	},
	bonds = {
		{ id = "ziz-fizziks", name = "Ziz Fizziks", note = "l'ingénieur qu'il remplaça" },
		{ id = "piznik", name = "Piznik", note = "envoyé dans les mines" },
		{ id = "gaxim-rustfizzle", name = "Gaxim Rustfizzle", note = "un gnome dans l'autre camp" },
	},
})

Translate("frFR", "piznik", {
	title = "Piznik",
	subtitle = "Mineur et espion",
	found = "À l'intérieur de la Mine des Cisailles",
	hint = [=[Cherchez dans la Mine des Cisailles le gobelin qui n'est pas aussi loyal qu'il le paraît.]=],
	allegiance = "La KapitalRisk · agent de Ziz Fizziks",
	sections = {
		{
			title = "Résumé",
			text = [=[Piznik était autrefois le deuxième gobelin le plus important du chantier de la {link:venture-company}KapitalRisk{/link} aux {link:stonetalon-mountains}Serres-Rocheuses{/link}. Puis {link:gerenzo-wrenchwhistle}Gerenzo{/link} prit le commandement, renvoya le patron de Piznik, {link:ziz-fizziks}Ziz Fizziks{/link}, et envoya Piznik travailler dans les mines. Ziz lui dit de rester et d'écouter. Il le fit, et il apprit que Gerenzo voulait une grande quantité d'un étrange minerai vert doré.]=],
		},
		{
			title = "Importance",
			text = [=[Piznik est la fissure dans le mur de la compagnie, un gobelin de l'intérieur qui guette pour son ancien maître.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il fait sortir en contrebande un échantillon du minerai vert doré de la Mine des {link:windshear-crag}Cisailles{/link}.
• Il prévoit de s'éclipser et de rejoindre {link:ziz-fizziks}Ziz{/link} une fois le vol découvert.]=],
		},
	},
	mentions = {
		{ text = "Les ordres de {link:gerenzo-wrenchwhistle}Gerenzo{/link}" },
		{ text = "Les ordres de {link:gerenzo-wrenchwhistle}Gerenzo{/link}" },
	},
	bonds = {
		{ id = "ziz-fizziks", name = "Ziz Fizziks", note = "son ancien patron" },
		{ id = "gerenzo-wrenchwhistle", name = "Gerenzo Wrenchwhistle", note = "l'envoya dans les mines" },
	},
})

Translate("frFR", "tsunaman", {
	title = "Tsunaman",
	subtitle = "Émissaire du Tribunal des marées",
	found = "Retraite de Roche-Soleil",
	hint = [=[Cherchez l'esprit de l'eau qui demeure parmi la Horde à Roche-Soleil.]=],
	allegiance = "Tribunal des marées · Horde",
	sections = {
		{
			title = "Résumé",
			text = [=[Tsunaman est un élémentaire d'eau venu à la {link:sun-rock-retreat}Retraite de Roche-Soleil{/link} pour une mission de guerre. Le Tribunal des marées l'envoya détruire les élémentaires de feu du {link:the-charred-vale}Val calciné{/link}, car Neptulon le Chasseur de marées, seigneur des élémentaires d'eau, veut que ses cousins de feu soient éteints. Leur guerre, dit-il, fait rage sur tous les plans depuis des âges.]=],
		},
		{
			title = "Importance",
			text = [=[Tsunaman montre que la ruine des {link:stonetalon-mountains}Serres-Rocheuses{/link} a attiré l'attention de puissances bien au-delà des montagnes. Le feu que les gobelins ont allumé dans le val est devenu un front dans une guerre bien plus ancienne entre les {link:elements}éléments{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il fait la guerre aux élémentaires de feu du {link:the-charred-vale}Val calciné{/link}.
• Il rapporte chaque victoire au Tribunal des marées.
• Il fait porter un message à {link:je-neu-sancrea}Je'neu Sancrea{/link}, à l'{link:zoram-gar-outpost}Avant-poste de Zoram'gar{/link}, en {link:ashenvale}Orneval{/link}.]=],
		},
	},
	mentions = {
		{ text = "La guerre des éléments" },
		{ text = "Des ennuis dans les profondeurs" },
	},
	bonds = {
		{ id = "tammra-windfield", name = "Tammra Windfield", note = "guérit ce que le feu a brûlé" },
	},
})

Translate("frFR", "braug-dimspirit", {
	title = "Braug Dimspirit",
	subtitle = "Chaman de l'épreuve du savoir",
	found = [=[Près du débouché de la Perce des Serres, côté Serres-Rocheuses]=],
	hint = [=[Trouvez le sage chaman qui campe près du tunnel menant à Orneval.]=],
	allegiance = "Horde · Thunder Bluff",
	aliases = { "Braug" },
	sections = {
		{
			title = "Résumé",
			text = [=[Braug Dimspirit est un chaman d'une grande sagesse qui tient son camp près de la {link:the-talondeep-path}Perce des Serres{/link}. Ceux qui cherchent l'épreuve du savoir viennent à lui après que {link:dorn-plainstalker}Dorn Plainstalker{/link} de {link:thousand-needles}Mille pointes{/link} a éprouvé leur corps. Braug éprouve l'esprit. Il croit que les gobelins, les elfes de la nuit et bien d'autres peuples partagent la responsabilité des malheurs de {link:kalimdor}Kalimdor{/link}, et non les seuls orcs et {link:forsaken}Réprouvés{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Braug perpétue une vieille tradition de la {link:horde}Horde{/link} : un héros doit connaître l'histoire du monde, et pas seulement savoir y combattre.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoie des chercheurs récupérer {i}Héritage des Aspects{/i} dans les profondeurs de {link:the-dor-danil-barrow-den}Dor'danil{/link}, au sud d'{link:ashenvale}Orneval{/link}.
• Il pose une question sur le livre, et attend la réponse aussi longtemps qu'il le faut.
• Il envoie ceux qui réussissent auprès de Parqual Fintallas, à {link:undercity}Undercity{/link}.]=],
