	hint = [=[Parlez au tauren endeuillé qui campe sur la route de l'ouest des Tarides.]=],
	allegiance = "Horde · Thunder Bluff",
	aliases = { "Makaba" },
	sections = {
		{
			title = "Résumé",
			text = [=[Makaba Flathoof est un {link:tauren}tauren{/link} dont le village fut attaqué par {link:grimtotem-clan}les Totem sinistre{/link}. Presque tous ses habitants furent tués. Makaba combattit, tua tous ceux qu'il put, et s'échappa de justesse. Il attend à présent au bord de la route, sous les montagnes, et il ne souhaite qu'une chose : que davantage de Totem sinistre soient morts. Il croyait sa fille {link:kaya-flathoof}Kaya{/link} perdue avec les autres.]=],
		},
		{
			title = "Importance",
			text = [=[Le chagrin de Makaba donne la mesure de ce que {link:grimtotem-clan}les Totem sinistre{/link} sont prêts à faire à leur propre peuple.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il demande vengeance contre {link:grimtotem-clan}les Totem sinistre{/link} du {link:grimtotem-post}Poste Totem sinistre{/link}.
• Il désigne {link:grundig-darkcloud}Grundig Darkcloud{/link} comme le chef de l'attaque.
• Il apprend que sa fille {link:kaya-flathoof}Kaya{/link} est vivante.]=],
		},
	},
	mentions = {
		{ text = "Vengez mon village" },
		{ text = "Tuer {link:grundig-darkcloud}Grundig Darkcloud{/link}" },
		{ text = "{link:kaya-flathoof}Kaya{/link} est vivante" },
	},
	bonds = {
		{ id = "kaya-flathoof", name = "Kaya Flathoof", note = "sa fille" },
		{ id = "grundig-darkcloud", name = "Grundig Darkcloud", note = "mena l'attaque" },
		{ id = "tammra-windfield", name = "Tammra Windfield", note = "la tante de Kaya" },
	},
})

