	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
			text = [=[Goggeroc est un terrestre, l'un des êtres de pierre que les légendes disent créés par les titans pour façonner la terre. Il dormit pendant des âges innombrables dans une gangue de résonite, profondément sous le {link:boulderslide-ravine}Ravin des Eboulis{/link}, jusqu'à ce que les kobolds creusent jusqu'à lui. Le chaman {link:mor-rogal}Mor'rogal{/link} craignait que, s'il se réveillait en pleine force, toutes les {link:stonetalon-mountains}Serres-Rocheuses{/link} soient perdues.]=],
		},
		{
			title = "Importance",
			text = [=[Goggeroc est un aperçu du plus ancien passé du monde, enfoui sous les pieds des vivants. S'il se réveilla dans la colère ou seulement dans la confusion, personne ne resta pour le lui demander.]=],
		},
	},
	mentions = {
		{ text = "Le réveil du terrestre" },
	},
	bonds = {
		{ id = "mor-rogal", name = "Mor'rogal", note = "craignait son réveil" },
	},
})

Translate("frFR", "ken-zigla", {
